function OwnerRight()
local RES= teamyar.query(context,[[{"query":"with recursive CTE_Account AS (SELECT ID as SourceAccount,ID as AccountID, CODE AS AccountCode, PARENT , ORG_ID AS ORG_ID FROM pa_account WHERE ORG_ID = 2 UNION SELECT  CTE_Account.SourceAccount as SourceAccount,pa.ID as AccountID, pa.CODE AS AccountCode, pa.PARENT , pa.ORG_ID AS ORG_ID FROM CTE_Account INNER JOIN pa_account as pa ON CTE_Account.AccountID = pa.PARENT and CTE_Account.ORG_ID = pa.ORG_ID), CTE_DateRangePerYear as (select min(JNDATE) as MinJndate,max(JNDATE) as MaxJndate,min(DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) as sdate,  max(DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) edate, JYEAR FROM REPORT_DIMDATE where (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) <= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) >= 133553537990000000)) OR (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) >= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) <= 133553537990000000)) OR (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) >= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) <= 133553537990000000)) OR (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) <= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) >= 133553537990000000)) group by JYEAR), CTE_VoucherRecords as  (select cte_DateRangePerYear.MaxJndate as Jndate,cte_DateRangePerYear.JYEAR,pv.ORG_ID,pvr.ACCOUNT_ID,SUM(COALESCE(pvr.CRD, 0) - COALESCE(pvr.DEB, 0)) as remain,TAG_ID from cte_DateRangePerYear inner join pa_voucher as pv on pv.RUN_DATE >= sdate and pv.RUN_DATE <= edate inner join pa_voucher_record as pvr on pv.ID = pvr.VOUCHER_ID and pv.ORG_ID = pvr.ORG_ID INNER JOIN PA_VOUCHER_RECORD_TAG vrt ON vrt.VOUCHER_RECORD_ID = pvr.ID and vrt.ORG_ID = pvr.ORG_ID  where pv.ORG_ID = 2 and (pv.RUN_DATE >=132922818000000000 and pv.RUN_DATE <= 133552800000000000) and pv.deleted = 0 and pvr.deleted = 0 group by MaxJndate,JYEAR,pv.ORG_ID,pvr.ACCOUNT_ID,vrt.TAG_ID) , CTE_MinDateRange AS (SELECT min(MinJndate) as MinJndate,min(JYEAR) JYEAR,min(sdate) sdate ,min(edate) edate FROM cte_DateRangePerYear), CTE_OpeningVoucherRecords as  (select CTE_MinDateRange.MinJndate AS Jndate,CTE_MinDateRange.JYEAR,pv.ORG_ID,pvr.ACCOUNT_ID,SUM(COALESCE(pvr.CRD, 0) - COALESCE(pvr.DEB, 0)) as remain,0 AS TAG from CTE_MinDateRange inner join pa_voucher as pv on pv.RUN_DATE >= sdate and pv.RUN_DATE <= edate inner join pa_voucher_record as pvr on pv.ID = pvr.VOUCHER_ID and pv.ORG_ID = pvr.ORG_ID left JOIN PA_VOUCHER_RECORD_TAG vrt ON vrt.VOUCHER_RECORD_ID = pvr.ID and vrt.ORG_ID = pvr.ORG_ID where pv.ORG_ID = 2 and (pv.RUN_DATE >=132922818000000000 and pv.RUN_DATE <= 133552800000000000) and pv.deleted = 0 and pvr.deleted = 0 AND vrt.TAG_ID IS NULL group by CTE_MinDateRange.MinJndate,CTE_MinDateRange.JYEAR,pv.ORG_ID,pvr.ACCOUNT_ID) , CTE_OpeningVoucherRecordsWithTag as (select CTE_MinDateRange.MinJndate AS Jndate,CTE_MinDateRange.JYEAR,pv.ORG_ID,pvr.ACCOUNT_ID,SUM(COALESCE(pvr.CRD, 0) - COALESCE(pvr.DEB, 0)) as remain,TAG_ID from CTE_MinDateRange inner join pa_voucher as pv on pv.RUN_DATE >= sdate and pv.RUN_DATE <= edate inner join pa_voucher_record as pvr on pv.ID = pvr.VOUCHER_ID and pv.ORG_ID = pvr.ORG_ID INNER JOIN PA_VOUCHER_RECORD_TAG vrt ON vrt.VOUCHER_RECORD_ID = pvr.ID and vrt.ORG_ID = pvr.ORG_ID where pv.ORG_ID = 2 and (pv.RUN_DATE >=132922818000000000 and pv.RUN_DATE <= 133552800000000000)  and pv.deleted = 0 and pvr.deleted = 0 group by CTE_MinDateRange.MinJndate,CTE_MinDateRange.JYEAR,pv.ORG_ID,pvr.ACCOUNT_ID,TAG_ID) ,CTE_AccountsVouchers AS (select CTE_Account.SourceAccount,CTE_Account.ORG_ID,sum(CTE_VoucherRecords.remain) as remain,CTE_VoucherRecords.Jndate,CTE_VoucherRecords.JYEAR,TAG_ID from CTE_Account INNER JOIN CTE_VoucherRecords on CTE_Account.AccountID=CTE_VoucherRecords.ACCOUNT_ID and CTE_Account.ORG_ID=CTE_VoucherRecords.ORG_ID group by CTE_Account.SourceAccount,CTE_Account.ORG_ID,CTE_VoucherRecords.Jndate,CTE_VoucherRecords.JYEAR,TAG_ID), CTE_AccountsVouchersInfo AS (select SourceAccount,ORG_ID,remain,Jndate,JYEAR,TAG_ID from CTE_AccountsVouchers UNION All select ACCOUNT_ID,ORG_ID,remain,Jndate,JYEAR,TAG_ID FROM CTE_OpeningVoucherRecordsWithTag UNION All select ACCOUNT_ID,ORG_ID,remain,Jndate,JYEAR,TAG FROM CTE_OpeningVoucherRecords), CTE_OwnerRightFund_T1 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 1 as type,TAG_ID from CTE_AccountsVouchersInfo where SourceAccount in(1252,1650,2151) and TAG_ID>=0 group by ORG_ID,Jndate,JYEAR,TAG_ID), CTE_OwnerRightCapitalIncreaseInFlow_T2 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 2 as type,TAG_ID from CTE_AccountsVouchersInfo where SourceAccount in(6063,2045,2151,2572,2161) and TAG_ID>=0 group by ORG_ID,Jndate,JYEAR,TAG_ID), CTE_OwnerRightSpendOnShares_T3 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 3 as type,TAG_ID from CTE_AccountsVouchersInfo where SourceAccount in(1617,1868,2152) and TAG_ID>=0 group by ORG_ID,Jndate,JYEAR,TAG_ID), CTE_OwnerRightSpendingOnTeasuryShares_T4 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 4 as type,TAG_ID from CTE_AccountsVouchersInfo where SourceAccount in(1617,2047,2161) and TAG_ID>=0 group by ORG_ID,Jndate,JYEAR,TAG_ID), CTE_OwnerRightLegalReserve_T5 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 5 as type,TAG_ID from CTE_AccountsVouchersInfo where SourceAccount in(1255,1611,2051,2160,1252,1650,2151) and TAG_ID>=0 group by ORG_ID,Jndate,JYEAR,TAG_ID), CTE_OwnerRightOtherReserves_T6 as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 6 as type,TAG_ID from CTE_AccountsVouchersInfo where SourceAccount in(1255,1611,2151,2051,1252,1650,2151) and TAG_ID>=0 group by ORG_ID,Jndate,JYEAR,TAG_ID), CTE_OwnerRightAssetRevaluationSurplus_T7 as  (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 7 as type,TAG_ID from CTE_AccountsVouchersInfo where SourceAccount in(2605,2144,2051,1252,1650,2151) and TAG_ID>=0 group by ORG_ID,Jndate,JYEAR,TAG_ID), CTE_OwnerRightForeignExchangeRateDiff_T8 as  (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 8 as type,TAG_ID from CTE_AccountsVouchersInfo where SourceAccount in(1253,2051,1252,1650,2151) and TAG_ID>=0 group by ORG_ID,Jndate,JYEAR,TAG_ID), CTE_OwnerRightAccumulatedProfit_T9 as  (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 9 as type,TAG_ID from CTE_AccountsVouchersInfo where SourceAccount in(2124,1650,2051,1252,1650,2151) and TAG_ID>=0 group by ORG_ID,Jndate,JYEAR,TAG_ID), CTE_OwnerRightTreasurayShares_T10 as  (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 10 as type,TAG_ID from CTE_AccountsVouchersInfo where SourceAccount in(1252,1650,2151) and TAG_ID>=0 group by ORG_ID,Jndate,JYEAR,TAG_ID), CTE_UNIONOwnerRight as (SELECT ORG_ID, REMAIN,JNDATE, JYEAR,TYPE,TAG_ID FROM CTE_OwnerRightFund_T1 UNION ALL SELECT ORG_ID, REMAIN,JNDATE, JYEAR,TYPE,TAG_ID FROM CTE_OwnerRightCapitalIncreaseInFlow_T2 UNION ALL SELECT ORG_ID, REMAIN,JNDATE, JYEAR,TYPE,TAG_ID FROM CTE_OwnerRightSpendOnShares_T3 UNION ALL SELECT ORG_ID, REMAIN,JNDATE, JYEAR,TYPE,TAG_ID FROM CTE_OwnerRightSpendingOnTeasuryShares_T4 UNION ALL SELECT ORG_ID, REMAIN,JNDATE, JYEAR,TYPE,TAG_ID FROM CTE_OwnerRightLegalReserve_T5 UNION ALL SELECT ORG_ID, REMAIN,JNDATE, JYEAR,TYPE,TAG_ID FROM CTE_OwnerRightOtherReserves_T6 UNION ALL SELECT ORG_ID, REMAIN,JNDATE, JYEAR,TYPE,TAG_ID FROM CTE_OwnerRightAssetRevaluationSurplus_T7 UNION ALL SELECT ORG_ID, REMAIN,JNDATE, JYEAR,TYPE,TAG_ID FROM CTE_OwnerRightForeignExchangeRateDiff_T8 UNION ALL SELECT ORG_ID, REMAIN,JNDATE, JYEAR,TYPE,TAG_ID FROM CTE_OwnerRightAccumulatedProfit_T9 UNION ALL SELECT ORG_ID, REMAIN,JNDATE, JYEAR,TYPE,TAG_ID FROM CTE_OwnerRightTreasurayShares_T10), cte_DecimalCount as (select ps.ORG_ID,ps.ID,ps.name,ps.DECIMAL_COUNT,ps.FEE_DECIMAL from PA_ORGANIZATIONS as po inner join PA_SYMBOLS as ps on po.BASE_CURRENCY = ps.id and po.ORG_ID = ps.ORG_ID), Cte_RemainAccountsBaseDecimalCount as (select uor.ORG_ID,oi.NAME as OrgName,  COALESCE(uor.remain, 0)/POWER(10, COALESCE(cdc.DECIMAL_COUNT, 0)) as remain , uor.JYEAR,uor.JNDATE, uor.type,uor.TAG_ID  from CTE_UNIONOwnerRight uor left join cte_DecimalCount cdc on uor.ORG_ID = cdc.ORG_ID left join org_info oi on uor.ORG_ID = oi.ID) SELECT JSON_ARRAYAGG(JSON_OBJECT('type',RA.type,'JYEAR',RA.JYEAR,'JNDATE',RA.JNDATE,'TAG_ID',RA.TAG_ID,'remain',RA.remain, 'title',PVT.NAME)) as result from Cte_RemainAccountsBaseDecimalCount RA LEFT JOIN pa_voucher_tag PVT ON  RA.ORG_ID = PVT.ORG_ID AND RA.TAG_ID = PVT.ID where RA.JYEAR>=0 order by RA.JYEAR ASC,RA.type;","params":[]}]]);
   teamyar.write_result(context,RES)
end

OwnerRight()

function OrgInfo()
    local orgName= teamyar.query(context,[[{"query":"select JSON_ARRAYAGG(JSON_OBJECT('orgName',NAME)) from org_info where ID= ?;","params":[2]}]]);
    teamyar.write_result(context,orgName)
end

OrgInfo()
